candidates.contract_code:
pub assume_specification[ core::cmp::Ordering::is_gt ](
    ordering: core::cmp::Ordering,
) -> (result: bool)
    ensures
        result == (ordering == core::cmp::Ordering::Greater),
;

pub assume_specification[ core::cmp::Ordering::is_le ](
    ordering: core::cmp::Ordering,
) -> (result: bool)
    ensures
        result == (
            ordering == core::cmp::Ordering::Less
                || ordering == core::cmp::Ordering::Equal
        ),
;

pub assume_specification[ core::cmp::Ordering::is_lt ](
    ordering: core::cmp::Ordering,
) -> (result: bool)
    ensures
        result == (ordering == core::cmp::Ordering::Less),
;

pub assume_specification[ core::cmp::Ordering::is_ne ](
    ordering: core::cmp::Ordering,
) -> (result: bool)
    ensures
        result == (ordering != core::cmp::Ordering::Equal),
;

pub assume_specification[ core::cmp::Ordering::reverse ](
    ordering: core::cmp::Ordering,
) -> (result: core::cmp::Ordering)
    ensures
        result == (match ordering {
            core::cmp::Ordering::Less => core::cmp::Ordering::Greater,
            core::cmp::Ordering::Equal => core::cmp::Ordering::Equal,
            core::cmp::Ordering::Greater => core::cmp::Ordering::Less,
        }),
;

pub assume_specification[ core::cmp::Ordering::then ](
    ordering: core::cmp::Ordering,
    other: core::cmp::Ordering,
) -> (result: core::cmp::Ordering)
    ensures
        result == (match ordering {
            core::cmp::Ordering::Equal => other,
            _ => ordering,
        }),
;
